mapper.select:
SELECT COALESCE (lw.num,0) as num, mc.market_tenant, mc.market_name FROM market_config mc left JOIN ( select market_tenant,market_name,count(id) as num from loose_works
and market_tenant = #{query.marketTenant}
and create_time >= #{query.period.begin} and create_time < #{query.period.end}
and completion_time >= #{query.completionPeriod.begin} and completion_time < #{query.completionPeriod.end}
group by market_tenant ) lw on mc.market_tenant = lw.market_tenant
mc.status = true
ORDER BY num DESC, mc.market_tenant

SELECT COALESCE (lw.num,0) as totalNum, mc.market_tenant, mc.market_name FROM market_config mc left JOIN ( select market_tenant,count(id) as num from loose_works
and market_tenant = #{query.marketTenant}
and create_time >= #{query.period.begin} and create_time < #{query.period.end}
and status = #{query.stateRange}
and has_problem = true
group by market_tenant ) lw on mc.market_tenant = lw.market_tenant
mc.status = true
ORDER BY totalNum DESC, mc.market_tenant

select count(lw.id) as total_num from loose_works lw left join market_config mc on mc.market_tenant = lw.market_tenant
mc.status = true
and lw.completion_time >= #{query.period.begin} and lw.completion_time < #{query.period.end}
and lw.market_tenant = #{query.marketTenant}

select
lw.*
from
loose_works lw
left join market_config mc on mc.market_tenant = lw.market_tenant

    mc.status = true

        and lw.create_time >= #{query.period.begin} and lw.create_time < #{query.period.end}


        and lw.market_tenant = #{query.marketTenant}


        and lw.status = #{query.status}


        and lw.has_problem != true


        and lw.has_problem = true


        and lw.supervise_dep = #{query.depId}


        and lw.completion_time >= #{query.completeTime.begin} and lw.completion_time <
        #{query.completeTime.end}


        and(
        lw.project_name like concat('%',#{query.keyword},'%')
        or
        lw.supervise_user_name like concat('%',#{query.keyword},'%')
        )

