SELECT COALESCE ( lw.num, 0 ) AS num, mc.market_tenant, mc.market_name FROM market_config mc LEFT JOIN ( SELECT `market_tenant`, count( 1 ) AS `num` FROM `loose_works_reform`
`create_time` between #{query.period.begin} and #{query.period.end}
and `market_tenant` in
#{item}
and `market_tenant` = #{query.marketTenant}
GROUP BY market_tenant ) lw ON mc.market_tenant = lw.market_tenant
mc.status = true
ORDER BY num DESC , mc.market_tenant

